values
  ('canon','house.vaering','House Vaering','skeldran','skeldra','approximate',225,null,null,null,null,'unknown',null,null,null,null,null,'character.vaer_the_red',null,null,'Skeldran royal house. Vaer the Red is the claimed ancestral founder; the earliest links remain traditional/uncertain while the later royal line is documented.','active','canonical','authored'),
  ('canon','house.marcellan','House Marcellan','asterian','asteria','unknown',null,null,null,null,null,'unknown',null,null,null,null,null,null,null,null,'Asterra republican oligarchic family. Aeson Marcellan is a League-era ancestor/political myth, but family prestige does not create a hereditary right to the First Archonship.','active','canonical','authored'),
  ('canon','house.valerian','House Valerian','asterian','asteria','unknown',null,null,null,null,null,'unknown',null,null,null,null,null,null,null,null,'Aurellian imperial dynasty with multiple historical imperial and cadet branches; Solvar Valerian I is a celebrated early ancestor rather than a proven founder record.','active','canonical','authored'),
  ('canon','house.asharan','House Asharan','serathi','serath','year',508,null,null,null,null,'unknown',null,null,null,null,null,'character.ashar_i_asharan',null,null,'Dynasty styled Asharan after Ashar I''s Covenant conversion and kingship; current legitimacy is deeply tied to Covenant history.','active','canonical','authored'),
  ('canon','house.tenrai','House Tenrai','kaishin','kaishin','unknown',null,null,null,null,null,'unknown',null,null,null,null,null,null,null,null,'Long-lived Kaishin imperial house. Tenrai Shun is a centralizing reform ancestor; current canon does not identify him as the literal founder.','active','canonical','authored'),
  ('canon','house.darcon','House Darcon','vesperan','crossroads','unknown',null,null,null,null,null,'unknown',null,null,null,null,null,null,null,null,'Vesperan imperial house whose survival depends on dynastic continuity, religious balancing, court politics, fortification, tolls, and diplomacy rather than simple inheritance alone.','active','canonical','authored')
