  ('canon','claim.freya.skeldran_crown.descent','character.freya_vaering','office.skeldra.king','direct_descent',null,null,'Direct child of Eirik IV. Leif remains the recognized legal heir.','["character.freya_vaering","character.eirik_iv_vaering"]'::jsonb,false,true,'unknown',null,null,null,null,null,'unknown',null,null,null,null,null,'canonical','authored'),
  ('canon','claim.freya.skeldran_crown.custom','character.freya_vaering','office.skeldra.king','customary_law',null,null,'Traditionalist and military support could invoke ancestral/customary arguments if succession fractures; this is not the current legal-heir designation.','[]'::jsonb,true,true,'unknown',null,null,null,null,null,'unknown',null,null,null,null,null,'canonical_uncertain','authored'),
  ('canon','claim.torvald.skeldran_crown','character.torvald_vaering','office.skeldra.king','direct_descent',null,null,'Direct child of Eirik IV, junior to the recognized legal heir; no exact statutory priority is invented here.','["character.torvald_vaering","character.eirik_iv_vaering"]'::jsonb,false,true,'unknown',null,null,null,null,null,'unknown',null,null,null,null,null,'canonical','authored'),
