  ('canon','history.event.ashar_conversion.503','conversion','Public Conversion of Ashar I','year',503,null,null,null,null,'region.serath','Ashar I publicly converted to the Covenant in 503 CR, helping reshape royal legitimacy.','canonical','authored',100,null,'0.6B',null),
  ('canon','history.event.ashar_kingship.508','coronation','Ashar I becomes King','year',508,null,null,null,null,'region.serath','Ashar I became king in 508 CR; the dynasty was thereafter styled Asharan.','canonical','authored',100,null,'0.6B',null),
  ('canon','history.event.cassian_valerian_death.612','death','Death of Cassian Valerian','year',612,null,null,null,null,'region.asteria','Lucan VII''s firstborn Cassian died at sea without issue in 612 CR.','canonical','authored',100,null,'0.6B',null),
  ('canon','history.event.julian_becomes_heir.612','other','Julian Valerian becomes current heir','year',612,null,null,null,null,'region.asteria','Cassian''s death without issue made Julian Valerian the current military heir.','canonical','authored',100,null,'0.6B',null),
  ('canon','history.event.mara_voss_election.623','election','Mara Voss elected High Captain','year',623,null,null,null,null,'origin.blackhaven','Mara Voss won the Blackhaven High Captain election through alliances, profitable raids, reputation, crew loyalty, and a coalition of rivals who preferred her to one another.','canonical','authored',100,null,'0.6B',null)
