-- Ebbing Tides Alpha 0.6B — Dynasties, Genealogy, Offices, Reigns & Claims
-- Global political/history population only. This does not make non-Skeldran regions traversable.
begin;
set constraints all deferred;

on conflict (world_scope_id,id) do update set
  name=excluded.name, culture_id=excluded.culture_id, region_id=excluded.region_id,
  founded_precision=excluded.founded_precision, founded_year=excluded.founded_year, founded_month=excluded.founded_month, founded_day=excluded.founded_day, founded_hour=excluded.founded_hour, founded_end_year=excluded.founded_end_year,
  ended_precision=excluded.ended_precision, ended_year=excluded.ended_year, ended_month=excluded.ended_month, ended_day=excluded.ended_day, ended_hour=excluded.ended_hour, ended_end_year=excluded.ended_end_year,
  founder_character_id=excluded.founder_character_id, parent_house_id=excluded.parent_house_id, cadet_branch_of_house_id=excluded.cadet_branch_of_house_id, notes=excluded.notes, status=excluded.status, canonical_status=excluded.canonical_status, origin=excluded.origin;

on conflict (world_scope_id,id) do update set
  runtime_character_id=excluded.runtime_character_id, lifecycle=excluded.lifecycle, name=excluded.name, sex=excluded.sex, ancestry_id=excluded.ancestry_id, homeland_region_id=excluded.homeland_region_id, culture_id=excluded.culture_id, religion_id=excluded.religion_id,
  birth_precision=excluded.birth_precision, birth_year=excluded.birth_year, birth_month=excluded.birth_month, birth_day=excluded.birth_day, birth_hour=excluded.birth_hour, birth_end_year=excluded.birth_end_year,
  death_precision=excluded.death_precision, death_year=excluded.death_year, death_month=excluded.death_month, death_day=excluded.death_day, death_hour=excluded.death_hour, death_end_year=excluded.death_end_year,
  social_status=excluded.social_status, house_id=excluded.house_id, notes=excluded.notes, canonical_status=excluded.canonical_status, origin=excluded.origin;

on conflict (world_scope_id,id) do nothing;

on conflict (world_scope_id,id) do update set name=excluded.name,institution_id=excluded.institution_id,region_id=excluded.region_id,selection_mode=excluded.selection_mode,hereditary_by_default=excluded.hereditary_by_default,notes=excluded.notes,canonical_status=excluded.canonical_status,origin=excluded.origin;

on conflict (world_scope_id,id) do nothing;

on conflict (world_scope_id,id) do nothing;

on conflict (world_scope_id,id) do nothing;

on conflict do nothing;

on conflict do nothing;

on conflict (world_scope_id,id) do nothing;

set constraints all immediate;
commit;

-- No save-schema bump in 0.6B: this pass expands canonical persistent world-history data only.
